CREATE TABLE IF NOT EXISTS workflows (id TEXT PRIMARY KEY, user_id TEXT, organization_id TEXT, name TEXT NOT NULL, description TEXT, definition JSONB DEFAULT '{}'::jsonb, published_version_id TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workflow_versions (id TEXT PRIMARY KEY, user_id TEXT, organization_id TEXT, workflow_id TEXT NOT NULL, definition JSONB DEFAULT '{}'::jsonb, version INT NOT NULL, published BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workflow_executions (id TEXT PRIMARY KEY, user_id TEXT, organization_id TEXT, workflow_id TEXT NOT NULL, status TEXT NOT NULL, input JSONB, output JSONB, logs TEXT[], created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
